#!/usr/bin/env bash
# Zion-PySDK — per-repo validation gate (stack: uv).
# Generated by tools/validate/generate.sh. Edit freely afterwards; the generator
# will not overwrite this file without --force.
#
#   quick   seconds. Repo-shape, lint, typecheck. No build.
#   full    minutes. Adds the test suite.
set -uo pipefail
# shellcheck source=lib/validate-lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/validate-lib.sh"

TIER="$(tier_or_die "${1:-quick}")"

# --- quick -----------------------------------------------------------------

assert "packaging metadata present" \
  'set -- $(ls pyproject.toml */pyproject.toml 2>/dev/null)
   [ "$#" -gt 0 ] || { echo "no pyproject.toml anywhere"; exit 1; }'

check "pyproject parses" "python3" \
  'python3 - <<PY
import glob, sys
try:
    import tomllib
except ModuleNotFoundError:
    sys.exit(77)
for f in glob.glob("pyproject.toml") + glob.glob("*/pyproject.toml"):
    tomllib.load(open(f, "rb"))
PY'

venv_ready() { [ -x .venv/bin/python ]; }

# PySDK is the one leaf that REGENERATES protos on purpose. The C++ ODR rule
# that forbids it in Client and Server does not apply here — stale stubs are a
# real defect, which is what gen-check exists to catch.
assert "sibling Zion-HAL checkout present" \
  'test -d ../Zion-HAL/protos || { echo "../Zion-HAL missing — make gen has nothing to generate from"; exit 1; }'

assert "generated proto stubs are committed, not ignored" \
  'ls zion-sdk/src/zion_sdk/_proto/*_pb2.py >/dev/null 2>&1 \
     || { echo "no committed stubs under _proto/ — the workflow expects them committed"; exit 1; }
   ! git check-ignore -q zion-sdk/src/zion_sdk/_proto 2>/dev/null \
     || { echo "_proto/ is gitignored; it must stay tracked"; exit 1; }'

# Known defect: `make gen` still points at the pre-rename Acadia-HAL path.
# Failing loudly here beats discovering it mid-loop.
assert "proto generation points at Zion-HAL, not the pre-rename path" \
  '! grep -rniE "acadia[-_]?hal" Makefile zion-sdk/tools/ 2>/dev/null \
     || { echo "generation still references Acadia-HAL — repoint it at Zion-HAL"; exit 1; }'

if venv_ready; then
  check "generated stubs are current" "make" 'make gen-check'
else
  block "generated stubs are current" "not run; .venv/bin/python missing — run: make setup"
fi

# Every make target here depends on INSTALL_STAMP, which rebuilds the venv. A
# missing or half-built .venv makes lint/typecheck/test exit 2 for a reason that
# has nothing to do with the code — BLOCKED, not FAIL.
if venv_ready; then
  check "lint" "make" 'make lint'
  check "typecheck" "make" 'make typecheck'
else
  block "lint" "not run; .venv/bin/python missing or venv half-built — run: make setup"
  block "typecheck" "not run; .venv/bin/python missing or venv half-built — run: make setup"
fi

[ "$TIER" = "quick" ] && { report "$TIER"; exit $?; }

# --- full ------------------------------------------------------------------

if venv_ready; then
  check "test suite" "make" 'make test'
else
  block "test suite" "not run; .venv/bin/python missing — run: make setup"
fi

report "$TIER"
